const body = $input.first().json;
const m = body.metricas || {};
const acciones = (body.acciones_destacadas || []).slice(0, 5);
const narrativa = (body.narrativa || '').trim();

const subject = `Ventas360 · Cierre ${new Date().toLocaleDateString('es-AR')} · ${m.ventas_dia ?? 0} ventas`;

const html = `
<p><strong>Resumen</strong></p>
<p>${narrativa.replace(/\n/g, '<br/>')}</p>
<ul>
  <li>Ventas: ${m.ventas_dia ?? 0} — $${Number(m.monto_ventas_dia || 0).toLocaleString('es-AR')}</li>
  <li>Pedidos pendientes: ${m.pedidos_pendientes ?? 0}</li>
  <li>Remitos por facturar: ${m.remitos_por_facturar ?? 0}</li>
  <li>Saldo a cobrar: $${Number(m.saldo_cobrar || 0).toLocaleString('es-AR')} (vencido $${Number(m.saldo_vencido || 0).toLocaleString('es-AR')})</li>
  <li>Bajo stock: ${m.articulos_bajo_stock ?? 0} · Sin stock: ${m.articulos_sin_stock ?? 0}</li>
</ul>
${acciones.length ? `<p><strong>Prioridades</strong></p><ol>${acciones.map((a) => `<li>${a}</li>`).join('')}</ol>` : ''}
<p style="color:#78716c;font-size:12px">Generado por n8n · Ventas360</p>
`;

return [{ json: { subject, html, narrativa, metricas: m } }];
